    # The rate of raw `pcm16` samples; the pack's when absent. For `wav` the header says, and a
    # value here must agree with it.
    sample_rate: Optional[int]
    # Force the spoken language, as for an `audio` input.
    language: Optional[str]
    # Text given to the decoder after the audio of every pass.
    prompt: Optional[str]
    # Text given to the decoder before the audio of every pass.
